#include "services/NotificationService.hpp"
#include "core/Logger.hpp"
#include <nlohmann/json.hpp>
#include <chrono>
#include <algorithm>
#include <fstream>
#include <format>
namespace Pine {NotificationService::NotificationService(std::filesystem::path root):path_(root/"notifications.json"){std::filesystem::create_directories(root);load();}void NotificationService::load(){try{if(!std::filesystem::exists(path_))return;nlohmann::json j;std::ifstream(path_)>>j;for(auto&v:j)items_.push_back({v.value("id",""),v.value("source",""),v.value("title",""),v.value("body",""),v.value("created_at",0LL),v.value("sensitive",false),v.value("read",false)});}catch(const std::exception&e){Logger::instance().error("NOTIFICATIONS",e.what());}}void NotificationService::save()const{try{nlohmann::json j=nlohmann::json::array();for(auto&i:items_)j.push_back({{"id",i.id},{"source",i.source},{"title",i.title},{"body",i.body},{"created_at",i.createdAt},{"sensitive",i.sensitive},{"read",i.read}});auto tmp=path_;tmp+=".tmp";std::ofstream(tmp)<<j.dump(2);std::error_code ec;std::filesystem::remove(path_,ec);std::filesystem::rename(tmp,path_);}catch(const std::exception&e){Logger::instance().error("NOTIFICATIONS",e.what());}}void NotificationService::postOnce(std::string id,std::string source,std::string title,std::string body,bool sensitive){std::scoped_lock lock(mutex_);if(std::ranges::any_of(items_,[&](const auto&n){return n.id==id;}))return;const auto stamp=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();items_.push_back({std::move(id),std::move(source),std::move(title),std::move(body),stamp,sensitive,false});if(items_.size()>200)items_.erase(items_.begin(),items_.begin()+static_cast<std::ptrdiff_t>(items_.size()-200));save();}void NotificationService::post(std::string source,std::string title,std::string body,bool sensitive){const auto stamp=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();postOnce(std::format("{:x}",stamp),std::move(source),std::move(title),std::move(body),sensitive);}std::vector<Notification>NotificationService::list()const{std::scoped_lock lock(mutex_);return items_;}void NotificationService::markRead(const std::string&id){std::scoped_lock lock(mutex_);for(auto&i:items_)if(i.id==id)i.read=true;save();}}
